// Generated by tour2playwright from a Tour Recorder export, then hand-edited.
// Source tour: Finance: Module Required Settings for New Users ( Configuration > Settings - All Sections ) - Full Flow
// Hand edits: setting blocks are found by their label text (the recording used row/column positions),
// wide viewport, login fallback, state assertions.
// READ-ONLY: this tour only LOOKS at the settings. It never changes a setting and never presses Save.
import { test, expect } from "../../../../core/fixtures/index";
import type { Page, Locator } from "@playwright/test";
import fs from "node:fs";

const SHOT_DIR = "tools/tour2playwright/generated/screenshots/finance-module-required-settings-for-new-users-configuration-settings-all-sections-full-flow";

// A step's own screenshot is taken BEFORE its action; this keeps one of the finished screen.
async function resultShot(page: Page, n: number) {
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/step-${String(n).padStart(2, "0")}-result.png` });
}

// Screenshot the current page with the target element outlined.
async function shot(page: Page, loc: Locator, file: string) {
  try {
    await loc.scrollIntoViewIfNeeded({ timeout: 5000 });
    await loc.evaluate((el) => el.setAttribute("data-t2p", "1"));
    await page.addStyleTag({
      content: '[data-t2p="1"]{outline:3px solid #e01e5a !important;outline-offset:2px !important;}',
    });
  } catch {}
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/${file}` });
  try { await loc.evaluate((el) => el.removeAttribute("data-t2p")); } catch {}
}

test.describe("Finance: Module Required Settings for New Users ( Configuration > Settings - All Sections ) - Full Flow @module:accounting @step:business @e2e", () => {
  // At the default 1280px some top-menu entries collapse into the "+" overflow.
  test.use({ viewport: { width: 1600, height: 900 } });

  test("Finance: Module Required Settings for New Users ( Configuration > Settings - All Sections ) - Full Flow", async ({ page }) => {
    test.setTimeout(240_000);
    await page.goto("/web");

    // The saved browser session can expire — fall back to the login form if we got bounced to it.
    const emailBox = page.getByRole("textbox", { name: "Email" });
    if (await emailBox.isVisible({ timeout: 8_000 }).catch(() => false)) {
      await emailBox.fill(process.env.ADMIN_EMAIL ?? "admin");
      await page.getByRole("textbox", { name: "Password" }).fill(process.env.ADMIN_PASSWORD ?? "admin");
      await page.getByRole("button", { name: "Log in" }).click();
      await page.waitForSelector(".o_main_navbar, .o_home_menu", { state: "visible", timeout: 45_000 });
    }
    await page.waitForLoadState("networkidle", { timeout: 10_000 }).catch(() => {});

    // Shared step runner: wait for the target, take the outlined screenshot, act, optionally keep a result shot.
    const run = async (n: number, title: string, loc: Locator, act?: (l: Locator) => Promise<void>, result = false) => {
      await test.step(`${String(n).padStart(2, "0")}. ${title}`, async () => {
        const l = loc.first();
        await l.waitFor({ state: "visible", timeout: 45000 });
        await shot(page, l, `step-${String(n).padStart(2, "0")}.png`);
        if (act) await act(l);
        if (result) await resultShot(page, n);
      });
    };
    // A settings block, found by the text it contains. The innermost matching block is used.
    const setting = (text: string | RegExp) =>
      page.locator(".o_setting_box").filter({ hasText: text }).filter({ hasNot: page.locator(".o_setting_box .o_setting_box") });
    // Look at one setting: it must be on the page. Nothing is clicked or changed.
    const look = (n: number, title: string, text: string | RegExp) =>
      run(n, title, setting(text), async (l) => { await expect(l, `setting "${text}" is on the page`).toBeVisible(); });

    await run(1, "Open the Accounting app", page.locator('[data-menu-xmlid="account_accountant.menu_accounting"]'), (l) => l.click());

    await test.step("02. Open the extra menu (+)", async () => {
      // On a wide window every menu entry fits, so there may be no "+" to click.
      const more = page.locator(".o_menu_sections_more button, .o_menu_sections .o_menu_sections_more").first();
      const target = (await more.isVisible({ timeout: 3000 }).catch(() => false)) ? more : page.locator(".o_menu_sections").first();
      await shot(page, target, "step-02.png");
    });

    await run(3, "Open Configuration > Settings",
      page.locator(".o_menu_sections .dropdown-toggle, .o_menu_sections > a").filter({ hasText: /^Configuration$/ }),
      async (l) => {
        await l.click();
        const item = page.locator(".dropdown-menu .dropdown-item").filter({ hasText: /^Settings$/ }).first();
        await item.waitFor({ state: "visible", timeout: 15000 });
        await resultShot(page, 3);
        await item.click();
        await expect(page.locator(".o_form_view"), "settings page opened").toBeVisible({ timeout: 45000 });
        await expect(page.locator(".o_setting_box").first(), "settings loaded").toBeVisible({ timeout: 45000 });
      }, false);

    await run(4, "You are on the Accounting settings tab", page.locator("div.tab.selected").filter({ hasText: /Accounting/ }), async (l) => {
      await expect(l).toBeVisible();
      await resultShot(page, 4);
    });

    await look(5, "Fiscal Localization", "Fiscal Localization");
    await look(6, "Taxes: Default Taxes", "Default Taxes");
    await look(7, "Taxes: Tax Return Periodicity", "Tax Return Periodicity");
    await look(8, "Taxes: Rounding Method", "Rounding Method");
    await look(9, "Currencies: Main Currency", "Main Currency");
    await look(10, "Currencies: Automatic Currency Rates", "Automatic Currency Rates");
    await look(11, "Customer Invoices: Default Sending Options", "Default Sending Options");
    await look(12, "Customer Invoices: Default Terms & Conditions", "Default Terms & Conditions");
    await look(13, "Customer Invoices: Sales Credit Limit", "Sales Credit Limit");
    await look(14, "Customer Payments section", "Invoice Online Payment");
    await look(15, "Vendor Bills: Purchase Receipt & digitisation", "Purchase Receipt");
    await look(16, "Vendor Payments: Checks", /Checks/);
    await look(17, "Default Accounts: Exchange difference", /Exchange Difference/i);
    await look(18, "Default Accounts: Bank suspense & outstanding accounts", /Bank Suspense/i);
    await look(19, "Default Accounts: Deferred entries", /Deferred/);
    await look(20, "Bank & Cash: statement import formats", /CSV, XLS/);
    await look(21, "Fiscal Periods: Fiscal Year", "Fiscal Year");
    await look(22, "Analytics: cost and budget tracking", "Analytic Accounting");
    await look(23, "Reporting: Add totals below sections", "Add totals below sections");

    // Step 24 only POINTS at Save — it is NOT pressed (settings are company-wide).
    await run(24, "Save your changes", page.locator('button[data-hotkey="s"], .o_form_button_save').first(), async (l) => {
      await expect(l, "Save button is present").toBeVisible();
    });
  });
});
